}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function listTools() {
  return [
    {
      name: 'slow_operation',
      description: 'Perform a slow operation subject to a request timeout.',
      inputSchema: {
        type: 'object',
        properties: {
          request_id: {
            type: 'string',
            description: 'Unique identifier for the request.',
          },
          delay_ms: {
            type: 'integer',
            description:
              'Simulated delay in milliseconds. Values 0..50 complete; values above 50 time out.',
          },
        },
        required: ['request_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'slow_operation') throw unknownTool(name);

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw invalidParams('arguments must be an object');
  }

  const allowed = ['request_id', 'delay_ms'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) throw invalidParams(`Unexpected field: ${key}`);
  }

  const { request_id, delay_ms } = args;
  if (typeof request_id !== 'string') {
    throw invalidParams('request_id is required and must be a string');
  }

  let delay = 0;
  if (delay_ms !== undefined) {
    if (!Number.isInteger(delay_ms)) throw invalidParams('delay_ms must be an integer');
    if (delay_ms < 0) throw invalidParams('delay_ms must be non-negative');
    delay = delay_ms;
  }

  if (delay > 50) {
    const err = new Error(`Operation timed out after ${delay}ms`);
    err.code = 'TIMEOUT';
    throw err;
  }

  await sleep(delay);

  return {
    content: [
      { type: 'text', text: `completed request ${request_id} after ${delay}ms` },
    ],
    isError: false,
  };
}

